const depositPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none}button{background:gold;font-weight:bold}.merchantBox{background:linear-gradient(135deg,#1a1a00,#2a2a00);border:2px solid gold;border-radius:16px;padding:16px;margin:16px 0;text-align:center}.merchantCode{font-size:38px;font-weight:900;color:gold}.copyBtn{width:auto;background:#fff;color:#000;padding:6px 14px;border-radius:20px;font-size:12px;font-weight:900;margin-left:8px}</style></head><body><div class='top' style='position:fixed;top:14px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.7);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px'>DEPOSIT • 7184154</div><a href='/dashboard' style='color:gold;margin-top:60px;display:inline-block'>← Back</a><div class='merchantBox'><div style='font-size:11px;color:#aaa'>AIRTEL MONEY • MERCHANT CODE</div><div style='display:flex;justify-content:center;align-items:center;margin:8px 0'><div class='merchantCode' id='mcode'>7184154</div><button class='copyBtn' onclick='copyCode()'>COPY</button></div></div><div style='background:rgba(18,22,35,0.85);padding:16px;border-radius:16px'><input id='am' type='number' placeholder='Amount'><input id='air' placeholder='Airtel No'><input type='file' id='file' accept='image/*'><div id='preview'></div><button onclick='dep()' id='b'>✅ Submit Deposit</button><div id='msg'></div></div><script>let uid=localStorage.getItem('uid'),b64='',h='';file.addEventListener('change',e=>{let f=e.target.files[0];let r=new FileReader();r.onload=()=>{b64=r.result;preview.innerHTML='<img src=\"'+b64+'\" style=\"max-width:100%\">';h=b64.length+'';};r.readAsDataURL(f);});async function dep(){let a=am.value.trim(),air=air.value.trim();if(!a||!air||!b64){msg.innerHTML='❌ Fill all';return;}b.disabled=true;let r=await fetch('/api/deposit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:parseInt(a),airtelNo:air,screenshot:b64,screenshotHash:h})});let j=await r.json();if(j.ok){msg.innerHTML='✅ Submitted!';setTimeout(()=>location.href='/dashboard',1200);}else{msg.innerHTML='❌ '+(j.error||'Failed');b.disabled=false;}}<\/script></body></html>";

const investPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{margin:0;padding:0;background:#0a0e1a;color:#fff;font-family:Arial;padding-bottom:90px}.top{position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:10;background:rgba(0,0,0,0.7);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px}.hdr{margin-top:60px;padding:16px}.clubGrid{display:grid;grid-template-columns:1fr;gap:12px;padding:0 12px}.clubCard{background:linear-gradient(135deg,rgba(255,255,255,0.08),rgba(255,255,255,0.02));border:1px solid rgba(255,215,0,0.2);border-radius:20px;padding:16px}.amtInput{flex:1;background:#000;border:1px solid gold;border-radius:12px;padding:12px;color:#fff}.invBtn{width:90px;background:gold;color:#000;font-weight:900;border-radius:12px;border:none;cursor:pointer}.inputRow{display:flex;gap:8px;margin-top:12px}</style></head><body><div class='top'>INVEST • Earn 10% Daily</div><div class='hdr'><h2>💎 Premium Football Investments</h2></div><div id='clubs' class='clubGrid'></div><script>let uid=localStorage.getItem('uid');const C=[{id:'arsenal',name:'Arsenal',rate:10,icon:'ARS',color:'#EF0107'},{id:'mancity',name:'Man City',rate:10,icon:'MCI',color:'#6CABDD'},{id:'liverpool',name:'Liverpool',rate:10,icon:'LIV',color:'#C8102E'},{id:'chelsea',name:'Chelsea',rate:8,icon:'CHE',color:'#034694'},{id:'manutd',name:'Man Utd',rate:8,icon:'MUN',color:'#DA020E'},{id:'tottenham',name:'Tottenham',rate:8,icon:'TOT',color:'#132257'}];clubs.innerHTML=C.map(c=>'<div class=clubCard><div style=\"display:flex;gap:12px\"><div style=\"width:48px;height:48px;border-radius:12px;background:'+c.color+';color:#fff;display:flex;align-items:center;justify-content:center;font-weight:900\">'+c.icon+'</div><div><b>'+c.name+'</b><div style=\"font-size:11px;color:#aaa\">'+c.rate+'% daily</div></div></div><div class=inputRow><input id=\"amt_'+c.id+'\" class=amtInput type=number placeholder=\"Amount\"><button class=invBtn onclick=\"investClub(\\''+c.id+'\\')\">INVEST</button></div></div>').join('');async function investClub(club){let a=document.getElementById('amt_'+club).value;if(!a||parseInt(a)<2000)return alert('Min 2000');let r=await fetch('/api/invest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,club,amount:parseInt(a)})});let j=await r.json();if(j.ok)alert('Invested');else alert(j.error);} <\/script><a href='/dashboard' style='color:gold;margin:12px;display:inline-block'>← Back</a></body></html>";

