const virtualPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1,viewport-fit=cover'>"+PWA_HEAD+"<style>body{margin:0;padding:0;padding-bottom:140px;background:#111;color:#fff;font-family:Arial}.top{position:fixed;top:calc(10px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);z-index:20;background:rgba(0,0,0,0.85);border:1px solid gold;padding:5px 16px;border-radius:20px;color:gold;font-size:11px}.tabPill{display:flex;background:#222;border-radius:30px;padding:5px;margin:calc(60px + env(safe-area-inset-top)) 12px 10px;gap:3px}.tab{flex:1;padding:10px;text-align:center;border-radius:20px;font-size:11px;color:#888;font-weight:900}.tab.active{background:#3a3a3a;color:#fff}.match{background:#2a2a2a;margin:8px 12px;border-radius:14px;padding:12px;border:1px solid #444}.match.live{background:#1e2e1e;border-color:#0f0;box-shadow:0 0 10px rgba(0,255,0,0.2)}.odd{flex:1;background:#3a3a3a;border-radius:8px;padding:10px;display:flex;justify-content:space-between;cursor:pointer}.odd.sel{background:#1a3d1a;border-color:#0f0}.bar{position:fixed;bottom:0;left:0;right:0;background:#b2ff00;color:#000;padding:14px;padding-bottom:calc(14px + env(safe-area-inset-bottom) + 12px);display:flex;justify-content:space-between;font-weight:900;z-index:99;box-shadow:0 -4px 20px rgba(0,0,0,0.8);border-top:2px solid #000}.sheet{position:fixed;bottom:0;left:0;right:0;background:#1e1e1e;max-height:85vh;overflow:auto;display:none;padding:14px;padding-bottom:calc(14px + env(safe-area-inset-bottom) + 20px);border-top:2px solid gold;z-index:100}.liveScore{background:#0f0;color:#000;padding:4px 12px;border-radius:20px;font-weight:900;font-size:13px;box-shadow:0 0 8px #0f0}.bettingTag{background:#ffcc00;color:#000;padding:4px 10px;border-radius:20px;font-weight:900;font-size:11px}.betSlipCard{background:#fff;color:#000;border-radius:12px;padding:10px;margin:8px 0;border-left:4px solid #000}.betSlipCard.won{border-left-color:#0f0}.betSlipCard.lost{border-left-color:#f44}.betSlipCard.pending{border-left-color:#ffcc00}.tableWrap{background:#1e1e1e;border-radius:16px;padding:0;overflow:hidden;border:1px solid #333;margin:10px 12px}.tableHead{background:#2a2a2a;padding:12px;display:flex;justify-content:space-between;font-size:11px;color:#888;font-weight:900;text-transform:uppercase;letter-spacing:1px}.tableRow{display:flex;justify-content:space-between;align-items:center;padding:10px 12px;border-bottom:1px solid #222;font-size:13px}.tableRow:last-child{border:none}.tableRow:nth-child(even){background:rgba(255,255,255,0.03)}.pos{width:26px;text-align:center;color:#888;font-weight:900}.teamName{flex:1;margin-left:10px;font-weight:700;display:flex;align-items:center;gap:6px}.pts{width:34px;text-align:center;font-weight:900;color:gold}.stat{width:28px;text-align:center;color:#aaa;font-size:12px}.gd{width:36px;text-align:center;color:#aaa}</style></head><body><div class='top'>MD <span id='topMD'>0</span> • VIRTUAL PREMIER LEAGUE</div><div class='tabPill'><div id='tabLive' class='tab active' onclick=\"switchTab('live')\">Live</div><div id='tabNext' class='tab' onclick=\"switchTab('next')\">Next</div><div id='tabTable' class='tab' onclick=\"switchTab('table')\">Table</div><div id='tabResults' class='tab' onclick=\"switchTab('results')\">Results</div><div id='tabBets' class='tab' onclick=\"switchTab('bets')\">My Bets</div></div><div id='liveSec'><div style='padding:0 12px;font-size:11px;display:flex;justify-content:space-between'><span id='phaseInfo'>BETTING</span><span id='timerTop' style='color:#ff6b00;font-weight:900'>02:00</span></div><div id='list'>Loading</div></div><div id='nextSec' style='display:none'><div id='nextList'></div></div><div id='tableSec' style='display:none'><div style='padding:8px 12px'><h3 style='color:gold;margin:8px 0'>🏆 League Table</h3><div class='tableWrap'><div class='tableHead'><span class='pos'>#</span><span class='teamName'>TEAM</span><span class='stat'>P</span><span class='stat'>W</span><span class='stat'>D</span><span class='stat'>L</span><span class='gd'>GD</span><span class='pts'>PTS</span></div><div id='tableBody'></div></div></div></div><div id='resultsSec' style='display:none'><div id='resList'></div></div><div id='betsSec' style='display:none'><div id='myBetsList' style='padding:12px'></div></div><div class='bar' onclick='openS()'><span>🎫 MD <span id='betMD'>0</span> x2.00</span><span id='lc' style='background:#000;color:#b2ff00;padding:6px 14px;border-radius:20px;font-size:13px'>0 legs</span></div><div class='sheet' id='sheet'><h3 style='color:gold'>Betslip <span id='sc'>0</span></h3><div id='sl'></div><input id='amt' type='number' value='500' style='width:100%;padding:12px;background:#111;color:#fff;border:1px solid gold;border-radius:10px;margin:8px 0'><button onclick='place()' style='width:100%;padding:12px;background:gold'>Place - Win to BALANCE</button><button onclick='closeS()' style='width:100%;padding:10px;background:#222;color:#fff;margin-top:8px'>Close</button></div><script>let sel=[],currentBetMD=0,uid=localStorage.getItem('uid'),lastTable={};function switchTab(t){document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.getElementById('tab'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');liveSec.style.display=t==='live'?'block':'none';nextSec.style.display=t==='next'?'block':'none';tableSec.style.display=t==='table'?'block':'none';resultsSec.style.display=t==='results'?'block':'none';betsSec.style.display=t==='bets'?'block':'none';if(t==='table')renderTable(lastTable);if(t==='results')loadRes();if(t==='bets')loadBets();}function tog(id,hs,as,p,md){let ex=sel.findIndex(s=>s.matchId===id);if(ex!==-1){if(sel[ex].prediction===p)sel.splice(ex,1);else sel[ex].prediction=p;}else{if(sel.length>=8)return alert('Max 8');sel.push({matchId:id,homeShort:hs,awayShort:as,prediction:p,md});}currentBetMD=md;rend();}function rend(){document.querySelectorAll('.odd').forEach(b=>b.classList.remove('sel'));sel.forEach(s=>{let e=document.querySelector('[data-m=\"'+s.matchId+'\"][data-p=\"'+s.prediction+'\"]');if(e)e.classList.add('sel');});sc.textContent=sel.length;lc.textContent=sel.length+' legs';betMD.textContent=currentBetMD||topMD.textContent;sl.innerHTML=sel.map(s=>'<div style=\"background:#2a2a2a;padding:6px;margin:3px 0;display:flex;justify-content:space-between\"><span>MD'+s.md+' '+s.homeShort+'-'+s.awayShort+' '+s.prediction+'</span><span onclick=\"remSel('+s.matchId+')\" style=\"color:red\">✕</span></div>').join('')||'Tap odds';}function remSel(id){sel=sel.filter(s=>s.matchId!==id);rend();}function openS(){sheet.style.display='block';}function closeS(){sheet.style.display='none';}async function place(){if(!sel.length)return alert('Add');let a=parseInt(amt.value);let r=await fetch('/api/virtual/bet/acca',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,selections:sel.map(s=>({matchId:s.matchId,homeTeam:s.homeShort,awayTeam:s.awayShort,prediction:s.prediction,md:s.md})),betMD:currentBetMD})});let j=await r.json();if(j.ok){alert('Placed MD'+j.md);sel=[];rend();closeS();switchTab('bets');}else alert(j.error);}function renderTable(tbl){lastTable=tbl;let arr=Object.values(tbl||{});arr.sort((a,b)=>{if(b.pts!==a.pts)return b.pts-a.pts;let gdA=a.gf-a.ga,gdB=b.gf-b.ga;return gdB-gdA;});let h='';arr.forEach((t,i)=>{let gd=t.gf-t.ga;let gdTxt=gd>0?'+'+gd:gd;let top3=i<3?'border-left:3px solid gold':'';let posColor=i===0?'color:gold':i<4?'color:#0f0':i>=13?'color:#f44':'color:#888';h+='<div class=\"tableRow\" style=\"'+top3+'\"><span class=\"pos\" style=\"'+posColor+'\">'+(i+1)+'</span><span class=\"teamName\">'+t.short+'</span><span class=\"stat\">'+t.pld+'</span><span class=\"stat\" style=\"color:#0f0\">'+t.w+'</span><span class=\"stat\" style=\"color:#aaa\">'+t.d+'</span><span class=\"stat\" style=\"color:#f44\">'+t.l+'</span><span class=\"gd\">'+gdTxt+'</span><span class=\"pts\">'+t.pts+'</span></div>';});tableBody.innerHTML=h||'<div style=\"padding:20px;text-align:center;color:#666\">Season starting...</div>';}function renderLive(fix,phase,md){let h='';(fix||[]).forEach(m=>{let isLive=phase!=='betting';h+='<div class=\"'+(isLive?'match live':'match')+'\"><div style=\"display:flex;justify-content:space-between;align-items:center\"><span style=\"font-weight:900\">'+m.home.short+' - '+m.away.short+'</span>'+(isLive?'<span class=liveScore>LIVE '+m.score+'</span>':'<span class=bettingTag>BETTING</span>')+'</div>'+(isLive?'<div style=\"text-align:center;margin-top:8px\"><div style=\"font-size:22px;font-weight:900;color:#0f0;text-shadow:0 0 10px #0f0\">'+m.score+' ⚽</div><div style=\"font-size:11px;color:#0f0\">'+m.result.toUpperCase()+'</div></div>':'')+'<div style=\"display:flex;gap:5px;margin-top:10px;'+(isLive?'opacity:0.3;pointer-events:none':'')+'\"><div class=odd data-m=\"'+m.id+'\" data-p=\"home\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'home\\','+md+')\"><span>1</span><span>2.00</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"draw\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'draw\\','+md+')\"><span>X</span><span>2.00</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"away\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'away\\','+md+')\"><span>2</span><span>2.00</span></div></div></div>';});list.innerHTML=h||'No fixtures';rend();}function renderNext(fix,md){let h='';(fix||[]).forEach(m=>{h+='<div class=match><span>'+m.home.short+' - '+m.away.short+'</span><div style=\"display:flex;gap:5px;margin-top:8px\"><div class=odd data-m=\"'+m.id+'\" data-p=\"home\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'home\\','+md+')\"><span>1</span><span>2.00</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"draw\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'draw\\','+md+')\"><span>X</span><span>2.00</span></div><div class=odd data-m=\"'+m.id+'\" data-p=\"away\" onclick=\"tog('+m.id+',\\''+m.home.short+'\\',\\''+m.away.short+'\\',\\'away\\','+md+')\"><span>2</span><span>2.00</span></div></div></div>';});nextList.innerHTML=h;}async function loadRes(){let r=await fetch('/api/virtual/results');let d=await r.json();let h='';d.forEach(m=>{h+='<div style=\"background:#1e1e1e;margin:8px;padding:8px;border-left:4px solid gold\">S'+m.season+' MD'+m.matchday+' ';m.fixtures.forEach(f=>{h+='<div style=\"display:flex;justify-content:space-between;font-size:12px;padding:4px 0\"><span>'+f.home.short+' vs '+f.away.short+'</span><b style=\"color:#0f0\">'+f.score+'</b><span>'+f.result.toUpperCase()+'</span></div>';});h+='</div>';});resList.innerHTML=h||'No results';}async function loadBets(){let r=await fetch('/api/virtual/my-bets/'+uid);let d=await r.json();let html='';d.slice(0,30).forEach(b=>{let sels=[];try{sels=JSON.parse(b.selections);}catch(e){}let status=b.status;let col=status==='won'?'won':status==='lost'?'lost':'pending';let icon=status==='won'?'✅ WON':status==='lost'?'❌ LOST':'⏳ PENDING';let winTxt=status==='won'?'+'+(b.winAmount||0)+' UGX':status==='pending'?'PENDING':'';html+='<div class=\"betSlipCard '+col+'\"><div style=\"display:flex;justify-content:space-between;font-weight:900;font-size:12px\"><span>🎫 MD'+b.matchday+' • '+b.amount+' UGX x '+b.odd+' = '+(b.amount*b.odd)+' UGX</span><span>'+icon+' '+winTxt+'</span></div><div style=\"margin-top:8px\">';sels.forEach(s=>{let ht=s.homeTeam||s.homeShort||'?';let at=s.awayTeam||s.awayShort||'?';let pred=s.prediction;let predTxt=pred==='home'?ht+' WIN':pred==='away'?at+' WIN':'DRAW';let pcol=pred==='home'?'#0f0':pred==='away'?'#f44':'#ffcc00';html+='<div style=\"display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid #eee\"><span>'+ht+' vs '+at+'</span><span style=\"background:'+pcol+';color:#000;padding:2px 6px;border-radius:10px;font-weight:900;font-size:10px\">'+predTxt+' ('+pred.toUpperCase()+')</span></div>';});html+='</div><div style=\"font-size:10px;color:#666;margin-top:6px\">'+new Date(b.createdAt).toLocaleString()+'</div></div>';});myBetsList.innerHTML=html||'No bets - place during BETTING';}async function sync(){let r=await fetch('/api/virtual/status');let d=await r.json();topMD.textContent=d.matchday;lastTable=d.table||{};let tl=d.timeLeft;let disp=Math.floor(tl/60)+':'+String(tl%60).padStart(2,'0');if(d.phase!=='betting'){if(d.phase==='first_half')disp='00:'+(45-tl);else if(d.phase==='halftime')disp='00:0'+tl;else{let tot=45+(45-tl);disp=String(Math.floor(tot/60)).padStart(2,'0')+':'+String(tot%60).padStart(2,'0');}}timerTop.textContent=disp;phaseInfo.textContent=d.phase.toUpperCase()+' MD'+d.matchday;let fix=d.phase==='betting'?d.currentFixtures:d.allLive;renderLive(fix||[],d.phase,d.matchday);renderNext(d.nextFixtures,d.nextMD);if(tableSec.style.display==='block')renderTable(d.table);if(currentBetMD===0)currentBetMD=d.phase==='betting'?d.matchday:d.nextMD;}sync();setInterval(sync,1000);setInterval(()=>{if(betsSec.style.display==='block')loadBets();},3000);<\/script></body></html>";

const withdrawPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}input,button{width:100%;padding:14px;margin:8px 0;border-radius:12px;border:none;box-sizing:border-box}button{background:gold;font-weight:bold}.card{background:rgba(18,22,35,0.9);padding:16px;border-radius:16px;border:1px solid #0f0}.pwdWrap{position:relative;width:100%}.pwdWrap input{padding-right:44px}.eye{position:absolute;right:12px;top:50%;transform:translateY(-50%);cursor:pointer;font-size:18px;user-select:none;color:#aaa}</style></head><body><div class='top' style='position:fixed;top:14px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.7);border:1px solid gold;padding:6px 18px;border-radius:30px;color:gold;font-size:11px'>WITHDRAW • Min 5k</div><a href='/dashboard' style='color:gold;margin-top:60px;display:inline-block'>← Back</a><h2>Withdraw BALANCE</h2><div class='card'><div id='bal' style='font-size:28px;color:#0f0;font-weight:900'>0</div><input id='am' type='number' placeholder='Min 5000'><input id='ph' placeholder='Airtel number to receive'><div class='pwdWrap'><input id='wpw' type='password' placeholder='🔑 Withdraw Password'><span class='eye' onclick=\"toggleEye()\">👁️</span></div><button onclick='wd()'>Withdraw</button><div id='msg'></div></div><div id='wlist'></div><script>let uid=localStorage.getItem('uid');function toggleEye(){let i=document.getElementById('wpw');i.type=i.type==='password'?'text':'password';}async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();bal.textContent=(u.gameBalance||0).toLocaleString()+' UGX';let r2=await fetch('/api/withdrawals/'+uid);let d=await r2.json();wlist.innerHTML=d.map(x=>'<div style=\"background:#1a1a1a;padding:8px;margin:4px 0\">'+x.amount+' to '+x.phone+' '+x.status+'</div>').join('');}async function wd(){let a=parseInt(am.value),ph=document.getElementById('ph').value,wpw=document.getElementById('wpw').value;if(a<5000)return msg.textContent='Min 5k';if(!wpw)return msg.textContent='Enter withdraw password';let r=await fetch('/api/withdraw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId:uid,amount:a,phone:ph,withdrawPassword:wpw})});let j=await r.json();msg.textContent=j.ok?'Sent - Awaiting approval':j.error;if(j.ok){am.value='';ph.value='';wpw.value='';}load();}load();<\/script></body></html>";

const historyPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}</style></head><body><div style='margin-top:20px'><a href='/dashboard' style='color:gold'>← Back</a><div id='list'></div></div><script>let uid=localStorage.getItem('uid');fetch('/api/history/'+uid).then(r=>r.json()).then(d=>{list.innerHTML=d.map(x=>'<div style=\"background:#1a1a1a;padding:8px;margin:4px 0\">'+x.type+' '+x.amount+' '+x.status+'</div>').join('')||'No data';});<\/script></body></html>";
const referralPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'>"+PWA_HEAD+"<style>body{background:#080a0f;color:#fff;font-family:Arial;padding:12px}.card{background:#fff;color:#000;padding:16px;border-radius:16px;margin:10px 0;border:2px solid gold}.refLink{width:100%;padding:12px;border-radius:10px;border:1px solid #ddd;font-size:12px}.teamItem{background:#1a1a1a;padding:10px;margin:6px 0;border-radius:10px;border-left:4px solid gold}</style></head><body><a href='/dashboard' style='color:gold;margin-top:10px;display:inline-block'>← Back</a><h2 style='color:gold'>👥 My Team</h2><div class='card'><div style='font-weight:900'>YOUR INVITE CODE</div><div id='code' style='font-size:28px;font-weight:900;color:#2f6bff;margin:8px 0'>---</div><input id='refLink' class='refLink' readonly><button onclick='copyRef()' style='background:#000;color:#fff;margin-top:8px'>COPY LINK</button><button onclick='shareWA()' style='background:#25D366;color:#fff'>WhatsApp</button></div><h3 style='color:gold'>Team (<span id='cnt'>0</span>)</h3><div id='team'>Loading...</div><script>let uid=localStorage.getItem('uid');function copyRef(){navigator.clipboard.writeText(refLink.value).then(()=>alert('Copied!'));}function shareWA(){window.open('https://wa.me/?text='+encodeURIComponent('Join: '+refLink.value));}async function load(){let r=await fetch('/api/user/'+uid);let u=await r.json();code.textContent=u.myReferralCode;refLink.value=location.origin+'/?ref='+u.myReferralCode;let r2=await fetch('/api/team/'+uid);let j=await r2.json();cnt.textContent=j.team.length;team.innerHTML=j.team.map(x=>'<div class=teamItem>'+x.fullName+' - '+x.phone+'</div>').join('')||'No team';}load();<\/script></body></html>";
const adminPage="<html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Admin</title><style>body{background:#000;color:#fff;padding:12px;font-family:Arial}input,button{width:100%;padding:8px;margin:4px 0;border-radius:8px;border:none}button{background:gold;font-weight:bold}.card{background:#111;padding:10px;margin:6px 0;border-radius:8px;border-left:4px solid gold}.tabs{display:flex;gap:4px;flex-wrap:wrap}.t{flex:1;min-width:60px;padding:10px;background:#222;border-radius:20px;text-align:center;cursor:pointer;font-size:11px;font-weight:900}.t.active{background:#fff;color:#000}img{max-width:100%}</style></head><body><div id='loginBox'><h2>Admin - Withdraw PWD + Fixed Table</h2><input id='pass' type='password' placeholder='LIFELINE123'><button onclick='check()'>Unlock</button></div><div id='adminBox' style='display:none'><h3>MD <span id='mdAdmin'>0</span></h3><div class='tabs'><div id='tbDep' class='t active' onclick=\"showTab('dep')\">Deposits</div><div id='tbWith' class='t' onclick=\"showTab('with')\">Withdraws</div><div id='tbUsers' class='t' onclick=\"showTab('users')\">Users</div><div id='tbBets' class='t' onclick=\"showTab('bets')\">Bets</div></div><button onclick='resetMD()' style='background:red;color:#fff'>RESET MD</button><button onclick='testTG()' style='background:#0af;color:#fff'>TEST TELEGRAM</button><div id='secDep'><div id='depAdmin'>Loading</div></div><div id='secWith' style='display:none'><div id='withAdmin'></div></div><div id='secUsers' style='display:none'><input id='search' placeholder='Search phone' oninput='filterU()' style='background:#222;color:#fff'><div id='usersAdmin'></div></div><div id='secBets' style='display:none'><div id='l'></div></div></div><script>const AP='LIFELINE123';let en='',allUsers=[];function check(){if(pass.value===AP){en=pass.value;loginBox.style.display='none';adminBox.style.display='block';loadAll();loadUsers();}}function showTab(t){document.querySelectorAll('.t').forEach(x=>x.classList.remove('active'));document.getElementById('tb'+t.charAt(0).toUpperCase()+t.slice(1)).classList.add('active');secDep.style.display=t==='dep'?'block':'none';secWith.style.display=t==='with'?'block':'none';secUsers.style.display=t==='users'?'block':'none';secBets.style.display=t==='bets'?'block':'none';}async function loadAll(){let r=await fetch('/api/admin/virtual?key='+en);let d=await r.json();mdAdmin.textContent=d.currentMD||0;l.innerHTML=(d.accas||[]).slice(0,20).map(a=>'<div class=card>MD'+a.matchday+' '+a.phone+' '+a.amount+'x'+a.odd+' '+a.status+'</div>').join('');let r2=await fetch('/api/admin/deposits?key='+en);let d2=await r2.json();depAdmin.innerHTML=d2.map(x=>'<div class=card><b>'+x.phone+' '+x.amount+'</b><br><img src=\"'+x.screenshot+'\" style=\"max-height:120px\"/><br><button onclick=\"approveDep('+x.id+','+x.userId+','+x.amount+')\" style=\"background:#0f0\">Approve</button> <button onclick=\"rejectDep('+x.id+')\" style=\"background:#f44\">Reject</button></div>').join('')||'No deposits';let r3=await fetch('/api/admin/withdrawals?key='+en);let d3=await r3.json();withAdmin.innerHTML=d3.map(x=>'<div class=card>'+x.phone+' '+x.amount+'<br><button onclick=\"approveWith('+x.id+')\" style=\"background:#0f0\">Approve</button><button onclick=\"rejectWith('+x.id+')\" style=\"background:#f44\">Refund</button></div>').join('')||'No withdraws';}async function loadUsers(){let r=await fetch('/api/admin/users?key='+en);let d=await r.json();allUsers=d;renderU(d);}function renderU(list){usersAdmin.innerHTML=list.map(u=>'<div class=card><b>'+(u.fullName||'')+' '+u.phone+'</b><br>WALLET:'+u.balance+' BAL:'+u.gameBalance+'<br>Login PWD:<b style=\"background:#222;padding:2px 6px\">'+u.password+'</b> Withdraw PWD:<b style=\"background:gold;color:#000;padding:2px 6px\">'+(u.withdrawPassword||'NOT SET')+'</b><br>Code:'+u.myReferralCode+' RefBy:'+u.referredBy+'<br><div style=\"display:flex;gap:4px\"><input id=\"np_'+u.id+'\" placeholder=\"New Login PWD\" style=\"background:#333;color:#fff\"><button onclick=\"resetPwd('+u.id+')\" style=\"background:#ff0;color:#000\">Reset Login</button></div><div style=\"display:flex;gap:4px;margin-top:4px\"><input id=\"nwp_'+u.id+'\" placeholder=\"New Withdraw PWD\" style=\"background:#333;color:#fff\"><button onclick=\"resetWPwd('+u.id+')\" style=\"background:gold;color:#000\">Reset Withdraw</button></div><div style=\"display:flex;gap:4px;margin-top:4px\"><input id=\"add_'+u.id+'\" type=\"number\" placeholder=\"Amt\" style=\"background:#333;color:#fff\"><button onclick=\"addBal('+u.id+',\\'wallet\\')\" style=\"background:#0f0\">+W</button><button onclick=\"addBal('+u.id+',\\'balance\\')\" style=\"background:#0af\">+B</button></div><button onclick=\"deleteUser('+u.id+',\\''+u.phone+'\\')\" style=\"background:#ff0000;color:#fff;margin-top:8px\">DELETE USER</button></div>').join('');}function filterU(){let q=search.value.toLowerCase();renderU(allUsers.filter(u=>u.phone.includes(q)));}async function approveDep(id,uid,amt){await fetch('/api/admin/approve-deposit?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,userId:uid,amount:amt})});loadAll();}async function rejectDep(id){await fetch('/api/admin/reject-deposit?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function approveWith(id){await fetch('/api/admin/approve-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function rejectWith(id){await fetch('/api/admin/reject-withdraw?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});loadAll();}async function resetPwd(uid){let np=document.getElementById('np_'+uid).value;if(!np)return alert('Enter');await fetch('/api/admin/reset-password?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,newPass:np})});alert('Reset');loadUsers();}async function resetWPwd(uid){let np=document.getElementById('nwp_'+uid).value;if(!np)return alert('Enter withdraw pwd');await fetch('/api/admin/reset-withdraw-password?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,newPass:np})});alert('Withdraw PWD Reset to '+np);loadUsers();}async function addBal(uid,type){let amt=parseInt(document.getElementById('add_'+uid).value);if(!amt)return alert('Amt');await fetch('/api/admin/add-balance?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid,amount:amt,type})});alert('Added');loadUsers();}async function deleteUser(uid,phone){if(!confirm('DELETE '+phone+'?'))return;let r=await fetch('/api/admin/delete-user?key='+en,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:uid})});let j=await r.json();if(j.ok){alert('Deleted');loadUsers();loadAll();}else alert('Failed');}async function testTG(){let r=await fetch('/api/admin/test-tg?key='+en,{method:'POST'});let j=await r.json();alert(j.ok?'Telegram sent!':'Failed');}async function resetMD(){await fetch('/api/admin/reset-md?key='+en,{method:'POST'});loadAll();}<\/script></body></html>";
