app.get('/api/admin/withdrawals',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[rows]=await db.query("SELECT * FROM withdrawals WHERE status='pending' ORDER BY id DESC LIMIT 40");res.json(rows);});
app.get('/api/admin/users',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json([]);const[rows]=await db.query("SELECT id,fullName,phone,password,withdrawPassword,balance,gameBalance,myReferralCode,referredBy FROM users ORDER BY id DESC LIMIT 300");res.json(rows);});
app.post('/api/admin/reset-password',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE users SET password=? WHERE id=?",[req.body.newPass,req.body.id]);res.json({ok:1});});
app.post('/api/admin/reset-withdraw-password',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE users SET withdrawPassword=? WHERE id=?",[req.body.newPass,req.body.id]);res.json({ok:1});});
app.post('/api/admin/add-balance',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});if(req.body.type==='wallet')await db.query("UPDATE users SET balance=balance+? WHERE id=?",[req.body.amount,req.body.id]);else await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[req.body.amount,req.body.id]);res.json({ok:1});});
app.post('/api/admin/delete-user',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});try{let id=req.body.id;await db.query("DELETE FROM deposits WHERE userId=?",[id]);await db.query("DELETE FROM withdrawals WHERE userId=?",[id]);await db.query("DELETE FROM investments WHERE userId=?",[id]);await db.query("DELETE FROM virtual_accas WHERE userId=?",[id]);await db.query("DELETE FROM users WHERE id=?",[id]);res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
app.post('/api/admin/approve-deposit',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE deposits SET status='approved' WHERE id=?",[req.body.id]);await db.query("UPDATE users SET balance=balance+? WHERE id=?",[req.body.amount,req.body.userId]);res.json({ok:1});});
app.post('/api/admin/reject-deposit',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE deposits SET status='rejected' WHERE id=?",[req.body.id]);res.json({ok:1});});
app.post('/api/admin/approve-withdraw',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});await db.query("UPDATE withdrawals SET status='approved' WHERE id=?",[req.body.id]);res.json({ok:1});});
app.post('/api/admin/reject-withdraw',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});const[w]=await db.query("SELECT * FROM withdrawals WHERE id=?",[req.body.id]);if(w[0])await db.query("UPDATE users SET gameBalance=gameBalance+? WHERE id=?",[w[0].amount,w[0].userId]);await db.query("UPDATE withdrawals SET status='rejected' WHERE id=?",[req.body.id]);res.json({ok:1});});
app.get('/api/admin/virtual',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});const[r2]=await db.query("SELECT a.*,u.phone FROM virtual_accas a JOIN users u ON a.userId=u.id ORDER BY a.id DESC LIMIT 50");res.json({accas:r2,currentMD:matchday+1});});
app.post('/api/admin/reset-md',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});matchday=0;season=1;seasonSchedule=genSched();currentFixtures=getFix(matchday);nextFixtures=getFix(matchday+1);virtualPhase='betting';virtualTimeLeft=120;liveFixtures=null;targetScores=null;pastResults=[];initTable();res.json({ok:1});});
app.post('/api/admin/test-tg',async(req,res)=>{if(req.query.key!==ADMIN_KEY)return res.status(401).json({});try{await tg(`🧪 <b>TEST OK</b> Fixed Table + Withdraw PWD ${new Date().toLocaleString()}`);res.json({ok:1});}catch(e){res.status(400).json({error:e.message});}});
